// --- Safely parse incoming transcript and check for undefined inputs ---
const rawInput = $input.first() && $input.first().json ? ($input.first().json.final_transcript || $input.first().json.SpeechResult || "") : "";
const transcript = String(rawInput).toLowerCase().trim();

const phone    = $input.first() && $input.first().json ? ($input.first().json.patient_phone || "") : "";
const callSid  = $input.first() && $input.first().json ? ($input.first().json.call_sid || "") : "";

// FIXED: Correctly check both n8n root JSON and the nested .query object for incoming Twilio parameters
const getParam = (key) => {
  const json = $input.first() && $input.first().json ? $input.first().json : {};
  // Check the query object first (where n8n puts URL parameters), then fall back to root level
  const val = (json.query && json.query[key] !== undefined) ? json.query[key] : json[key];

  if (val === undefined || val === null || val === "" || val === "null" || val === "undefined") {
    return null;
  }
  try {
    return typeof val === 'string' ? decodeURIComponent(val) : String(val);
  } catch (e) {
    return String(val);
  }
};

const prevName       = getParam('prev_name');
const prevDate       = getParam('prev_date');
const prevReason     = getParam('prev_reason');
const prevBookingFor = getParam('prev_booking_for');
const prevTimeSlot   = getParam('prev_time_slot');
const attempt        = getParam('attempt') || "1";

const slots = {
  name: null,
  date: null,
  reason: null,
  raw_text: transcript,
  phone: phone,
  call_sid: callSid
};

// --- 1. RELATION & BOOKING FOR DETECTION ---
slots.booking_for = "Self";
const relations = {
  "मां": "Mother", "माँ": "Mother", "मम्मी": "Mother", "पापा": "Father", "पिता": "Father",
  "बेटी": "Daughter", "बेटे": "Son", "पत्नी": "Wife", "पति": "Husband", "भाई": "Brother", "बहन": "Sister",
  "papa": "Father", "pita": "Father", "maa": "Mother", "mummy": "Mother", "beti": "Daughter", "beta": "Son", "bhai": "Brother", "behen": "Sister"
};
for (const [hindi, english] of Object.entries(relations)) {
  if (transcript.includes(hindi)) { 
    slots.booking_for = english; 
    break; 
  }
}
slots.booking_for = (slots.booking_for !== "Self") ? slots.booking_for : (prevBookingFor || "Self");


// --- 2. NAME EXTRACTION ---
const namePatterns = [
  /mera\s+naam\s+([a-z0-9\u0900-\u097F]+(?:\s+[a-z0-9\u0900-\u097F]+)?)/i,
  /naam\s+([a-z0-9\u0900-\u097F]+(?:\s+[a-z0-9\u0900-\u097F]+)?)\s*(?:hai)?/i,
  /(?:unka|uska|inka|unki|uski)\s+naam\s+([^\s,।]+(?:\s+[^\s,।]+)?)/i,
  /(?:मेरा\s+नाम|नाम)\s+([^\s,।]+(?:\s+[^\s,।]+)?)\s*(?:है|हूँ)?/,
  /मैं\s+([^\s,।]+(?:\s+[^\s,।]+)?)\s*(?:हूँ|बोल\s+रह)/,
  /([^\s,।]+(?:\s+[^\s,।]+)?)\s+के\s+लिए\s+(?:अपॉइंटमेंट|appointment|दिखाना)/i,
  /([^\s,।]{2,})\s+बोल\s+रह[ाी]/
];

for (const pattern of namePatterns) {
  const match = transcript.match(pattern);
  if (match) { 
    slots.name = match[1].replace(/\s*(है|हूँ|hai|hoon)\s*$/i, "").trim(); 
    break; 
  }
}

if (!slots.name && (!prevName || prevName === "Unknown") && transcript.split(/\s+/).length <= 2 && transcript.length > 2) {
  slots.name = transcript.replace(/[.,। है हूं hai hoon]/g, "").trim();
}

if (slots.name) {
  slots.name = slots.name.replace(/^(dr|dr\.|doctor|mr|mr\.|mister|shri|shree|ji|डॉ|डॉक्टर|श्री|जी)\s+/i, "").trim();
  slots.name = slots.name.replace(/\s+(ji|जी)$/i, "").trim();
}

const notNames = ["कल", "आज", "परसों", "बुखार", "खांसी", "दर्द", "नहीं", "है", "हूँ", "आना", "जाना", "थोड़ा", "सांस", "kal", "aaj", "parso", "fever", "bukhar", "appointment", "subah", "shaam", "dopahar", "shyam", "morning", "evening", "appointment"];
if (slots.name && notNames.includes(slots.name.toLowerCase())) {
  slots.name = null;
}


// --- 3. DATE EXTRACTION ---
const today = new Date();
const tomorrow = new Date(today); tomorrow.setDate(today.getDate() + 1);
const dayAfter = new Date(today); dayAfter.setDate(today.getDate() + 2);

const monthMap = {
  "जनवरी":0,"फरवरी":1,"मार्च":2,"अप्रैल":3,"मई":4,"जून":5,"जुलाई":6,"अगस्त":7,"सितंबर":8,"अक्टूबर":9,"नवंबर":10,"दिसंबर":11,
  "january":0,"february":1,"march":2,"april":3,"may":4,"june":5,"july":6,"august":7,"september":8,"october":9,"november":10,"december":11,
  "jan":0,"feb":1,"mar":2,"apr":3,"jun":5,"jul":6,"aug":7,"sept":8,"oct":9,"nov":10,"dec":11
};

if (transcript.includes("आज") || transcript.includes("aaj")) {
  slots.date = today.toLocaleDateString("en-IN");
} else if (transcript.includes("कल") || transcript.includes("kal")) {
  slots.date = tomorrow.toLocaleDateString("en-IN");
} else if (transcript.includes("परसों") || transcript.includes("parso")) {
  slots.date = dayAfter.toLocaleDateString("en-IN");
} else {
  let dateMatched = false;

  for (const [monthName, monthNum] of Object.entries(monthMap)) {
    const monthPattern = new RegExp(`(\\d{1,2})(?:st|nd|rd|th)?\\s*${monthName}`, 'i');
    const match = transcript.match(monthPattern);
    if (match) {
      const d = new Date(today.getFullYear(), monthNum, parseInt(match[1]));
      slots.date = d.toLocaleDateString("en-IN");
      dateMatched = true;
      break;
    }
  }

  if (!dateMatched) {
    const fallbackMatch = transcript.match(/\d{1,2}/);
    if (fallbackMatch) {
      const targetDay = parseInt(fallbackMatch[0]);
      if (targetDay >= 1 && targetDay <= 31) {
        let targetMonth = today.getMonth();

        if (targetDay < today.getDate() || transcript.includes("agle mahine") || transcript.includes("अगले महीने")) {
          targetMonth += 1;
        }

        const d = new Date(today.getFullYear(), targetMonth, targetDay);
        slots.date = d.toLocaleDateString("en-IN");
      }
    }
  }
}


// --- 4. MEDICAL REASON EXTRACTION ---
const medicalKeywords = [
  "bukhaar", "bukhar", "khansi", "sardee", "sardi", "dard", "pet", "sir", "headache", "stomach",
  "बुखार","खांसी","सर्दी","दर्द","चोट","जाँच","checkup","चेकअप",
  "उल्टी","दस्त","सिरदर्द","पेट दर्द","कमर दर्द","आँख","teeth",
  "कान","गला","दांत","एलर्जी","डायबिटीज","शुगर","सांस","थकान","बीपी","bp","fever","dikhana","दिखाना","pain","दवाई","cough",
  "vomiting", "weakness", "allergy", "infection", "consultation", "consult"
];

const vagueDistressPhrases = [
  "tabiyat kharab", "tabiyat khraab", "tabiat kharab", "तबीयत खराब",
  "bimar hu", "bimar hoon", "बीमार", "swasthya", "theek nahi", "thik nahi"
];

for (const kw of medicalKeywords) {
  if (transcript.includes(kw.toLowerCase())) {
    slots.reason = kw;
    break;
  }
}

if (!slots.reason) {
  const isVague = vagueDistressPhrases.some(phrase => transcript.includes(phrase));
  if (isVague) {
    slots.reason = "General Checkup";
  } else {
    const reasonMatch = transcript.match(/(?:के\s+लिए|की\s+समस्या|तकलीफ|liye|problem|vajah\s+se)\s*(.{0,30})/i);
    if (reasonMatch) slots.reason = reasonMatch[0].trim();
  }
}


// --- 5. TIME SLOT EXTRACTION (IMPROVED - PREVENTS LOOPING) ---

// First: Handle specific times like "subah 10 baje" or "shaam 5 baje"
const timePatterns = [
  { re: /(?:subah|सुबह|morning)\s*(\d{1,2})/i,                        period: "Morning",   offset: 0  },
  { re: /(?:dopahar|दोपहर|afternoon|dophr|dopar|dopahra)\s*(\d{1,2})/i,period: "Afternoon", offset: 12 },
  { re: /(?:shaam|शाम|sham|shyam|evening|shaah)\s*(\d{1,2})/i,         period: "Evening",   offset: 12 },
  { re: /(?:raat|रात|night)\s*(\d{1,2})/i,                             period: "Night",     offset: 12 }
];

slots.time_slot = null;
slots.time_slot_display = null;

// Try matching specific time patterns first
for (const p of timePatterns) {
  const m = transcript.match(p.re);
  if (m) {
    let hour = parseInt(m[1]);
    if (hour >= 1 && hour <= 12) {
      const h24 = (p.offset === 12 && hour < 12) ? hour + 12 : hour;
      slots.time_slot         = `${p.period} ${String(h24).padStart(2, "0")}:00`;
      slots.time_slot_display = `${p.period} ${String(h24).padStart(2, "0")}:00`;
      break;
    }
  }
}

// If no specific time matched, try to match the period (subah/shaam/dopahar)
if (!slots.time_slot) {

  // EXPANDED word lists with ALL possible Twilio misrecognitions
  const morningWords = [
    "subah", "subha", "subhah", "subh", "sabah", "supah", "supha",
    "सुबह", "सुभा",
    "morning", "marning", "morng", "morn",
    // Phonetic variations Twilio might return
    "soobah", "soobha", "subbah", "subba"
  ];

  const afternoonWords = [
    "dopahar", "dupahar", "dopar", "dupar", "dophar", "dophar", "dophr", "dopahra",
    "दोपहर", "दुपहर",
    "afternoon", "afternun", "aftarnun", "noon",
    // Phonetic variations
    "dobahar", "duphar", "dopahr", "duppahar"
  ];

  const eveningWords = [
    "shaam", "sham", "shyam", "shaah", "shaamm", "shaamm",
    "शाम", "शम",
    "evening", "evning", "evenin", "eve",
    // Phonetic variations - THIS IS WHERE YOUR BUG WAS!
    "sam", "saam", "shamm", "sham", "shhm", "sh am", "sha am", "sha m",
    "shyam", "shyaam", "siyam"
  ];

  const nightWords = [
    "raat", "रात", "night", "nait", "nite", "niat"
  ];

  // Function to check if any word from a list appears in the transcript
  const matchAny = (wordList, text) => {
    // Remove spaces from text for comparison (handles "sh am" -> "sham")
    const cleanText = text.replace(/\s+/g, "");
    for (const word of wordList) {
      if (text.includes(word) || cleanText.includes(word.replace(/\s+/g, ""))) {
        return true;
      }
    }
    return false;
  };

  // Check each time period
  if (matchAny(morningWords, transcript)) {
    slots.time_slot = "Morning";
    slots.time_slot_display = "Morning (9:00-12:00)";
  }
  else if (matchAny(afternoonWords, transcript)) {
    slots.time_slot = "Afternoon";
    slots.time_slot_display = "Afternoon (12:00-16:00)";
  }
  else if (matchAny(eveningWords, transcript)) {
    slots.time_slot = "Evening";
    slots.time_slot_display = "Evening (16:00-19:00)";
  }
  else if (matchAny(nightWords, transcript)) {
    slots.time_slot = "Night";
    slots.time_slot_display = "Night (19:00-21:00)";
  }

  // ============================================================
  // CRITICAL FIX: Fallback for when Twilio returns garbled text
  // but we know the user SAID something (not silence)
  // ============================================================
  if (!slots.time_slot && transcript.length > 0) {

    // Phonetic first-letter matching
    const firstChar = transcript.charAt(0);
    const firstTwoChars = transcript.substring(0, 2).replace(/\s+/g, "");

    // "shaam" starts with "sh", "subah" starts with "su", "dopahar" starts with "do"
    if (firstTwoChars === "sh" || firstTwoChars === "sa" || firstChar === "श") {
      slots.time_slot = "Evening";
      slots.time_slot_display = "Evening (16:00-19:00)";
    }
    else if (firstTwoChars === "su" || firstTwoChars === "so" || firstChar === "सु") {
      slots.time_slot = "Morning";
      slots.time_slot_display = "Morning (9:00-12:00)";
    }
    else if (firstTwoChars === "do" || firstTwoChars === "du" || firstChar === "दो") {
      slots.time_slot = "Afternoon";
      slots.time_slot_display = "Afternoon (12:00-16:00)";
    }
    else if (firstTwoChars === "ra" || firstChar === "रा") {
      slots.time_slot = "Night";
      slots.time_slot_display = "Night (19:00-21:00)";
    }

  }
}

// --- 6. CRASH-PROOFED HISTORY MERGING ---
const correctionKeywords = ["nahi", "nahin", "नहीं", "galat", "गलत", "actually", "change", "badlo", "बदलो", "wrong"];
const hasCorrection = correctionKeywords.some(k => transcript.includes(k));

slots.name   = slots.name   ? slots.name   : (hasCorrection ? null : prevName);
slots.date   = slots.date   ? slots.date   : (hasCorrection ? null : prevDate);
slots.reason = slots.reason ? slots.reason : (hasCorrection ? null : prevReason);

const extractedTimeSlot = slots.time_slot;
slots.time_slot         = extractedTimeSlot ? extractedTimeSlot : (hasCorrection ? null : prevTimeSlot);
slots.time_slot_display = slots.time_slot_display || slots.time_slot || null;
slots.prev_time_slot    = slots.time_slot || "";


// --- 7. STRICT EMPTY SLOT CHECK WITH RETRY LIMIT ---
const currentAttempt = parseInt(attempt) || 1;
const maxAttempts = 3; // Maximum times to ask for same slot

slots.missing = [];

// Check each slot, but respect the retry limit
if (!slots.name || slots.name === "Unknown" || slots.name === "") {
  // Only ask for name again if we haven't asked 3 times already
  if (currentAttempt < maxAttempts) {
    slots.missing.push({ field: "name", hindi: "आपका नाम" });
  } else {
    // After 3 failed attempts, use a placeholder to prevent infinite loop
    slots.name = "Patient";
  }
}

if (!slots.date || slots.date === "Not provided" || slots.date === "") {
  if (currentAttempt < maxAttempts) {
    slots.missing.push({ field: "date", hindi: "अपॉइंटमेंट की तारीख" });
  } else {
    // After 3 failed attempts, default to tomorrow
    const tomorrow = new Date();
    tomorrow.setDate(tomorrow.getDate() + 1);
    slots.date = tomorrow.toLocaleDateString("en-IN");
  }
}

if (!slots.time_slot || slots.time_slot === "Not provided" || slots.time_slot === "") {
  if (currentAttempt < maxAttempts) {
    slots.missing.push({ field: "time_slot", hindi: "कौन से समय पर आना है, सुबह या शाम" });
  } else {
    // After 3 failed attempts, default to morning
    slots.time_slot = "Morning";
    slots.time_slot_display = "Morning (9:00-12:00)";
  }
}

if (!slots.reason || slots.reason === "Not provided" || slots.reason === "") {
  if (currentAttempt < maxAttempts) {
    slots.missing.push({ field: "reason", hindi: "बीमारी का कारण" });
  } else {
    // After 3 failed attempts, default to general checkup
    slots.reason = "General Checkup";
  }
}




slots.all_collected = slots.missing.length === 0;

const filledNewSlot = 
  (slots.name && !prevName) ||
  (slots.date && !prevDate) ||
  (slots.reason && !prevReason) ||
  (slots.time_slot && !prevTimeSlot);

if (transcript.length === 0 || filledNewSlot) {
  slots.attempt = "1";
} else {
  slots.attempt = String(currentAttempt + 1);
}

return [{ json: slots }];

const input = $input.first().json;
const missing = input.missing || [];

// Handle wrong number
if (input.is_wrong_number) {
  return [{ json: {
    twiml: `<?xml version="1.0" encoding="UTF-8"?><Response><Say language="hi-IN">Koi baat nahi. Agar aapko appointment chahiye toh dobara call karein. Dhanyavaad!</Say><Hangup/></Response>`,
    gave_up: true
  }}];
}

function buildQuestion(missingSlots) {
  if (missingSlots.length === 0) return "धन्यवाद! आपकी जानकारी दर्ज कर ली गई है।";
  const first = missingSlots[0].field;
  const questions = {
    name:      "क्षमा करें, मुझे आपका नाम सुनाई नहीं दिया। कृपया अपना पूरा नाम बताएं।",
    date:      "धन्यवाद! अब कृपया बताएं आप किस तारीख को अपॉइंटमेंट लेना चाहते हैं?",
    time_slot: "ठीक है! आप कौन सा समय चाहते हैं — सुबह, दोपहर, या शाम?",
    reason:    "कृपया बताएं आपको किस समस्या के लिए डॉक्टर से मिलना है?"
  };
  return questions[first] || `कृपया अपना ${missingSlots[0].hindi} बताएं।`;
}

const targetQuestion = buildQuestion(missing);
const attempt = parseInt(input.attempt || "1") + 1;

const partialData = {
  name:        input.name        || input.prev_name        || "Unknown",
  date:        input.date        || input.prev_date        || "Not provided",
  reason:      input.reason      || input.prev_reason      || "Not provided",
  time_slot:   input.time_slot   || input.prev_time_slot   || "Not provided",
  booking_for: input.booking_for || input.prev_booking_for || "Self",
  phone:       input.phone       || "",
  call_sid:    input.call_sid    || "",
  raw_text:    input.raw_text    || "",
  status:      "Incomplete"
};

if (attempt > 3) {
  return [{ json: {
    twiml: `<?xml version="1.0" encoding="UTF-8"?><Response><Say language="hi-IN">Kshama karein, aap baad mein call karein. Dhanyavaad!</Say><Hangup/></Response>`,
    gave_up: true,
    ...partialData
  }}];
}

const prevName       = encodeURIComponent(partialData.name);
const prevDate        = encodeURIComponent(partialData.date);
const prevReason      = encodeURIComponent(partialData.reason);
const prevTimeSlot    = encodeURIComponent(partialData.time_slot);
const prevBookingFor  = encodeURIComponent(partialData.booking_for);

const queryParams = `attempt=${attempt}&prev_name=${prevName}&prev_date=${prevDate}&prev_reason=${prevReason}&prev_time_slot=${prevTimeSlot}&prev_booking_for=${prevBookingFor}`;

const baseUrl = "https://grope-tanned-overcook.ngrok-free.dev/webhook/doctor-bot";
const actionUrl = `${baseUrl}?${queryParams}`;
const safeActionUrl = actionUrl.replace(/&/g, '&amp;');

const twiml = `<?xml version="1.0" encoding="UTF-8"?><Response><Gather input="speech" language="hi-IN" speechTimeout="5" action="${safeActionUrl}" method="POST"><Say language="hi-IN">${targetQuestion}</Say></Gather><Say language="hi-IN">क्षमा करें, कृपया दोबारा कॉल करें।</Say></Response>`;

return [{ json: {
  twiml,
  question_asked: targetQuestion,
  attempt,
  gave_up: false,
  ...partialData
}}];

// 1. Fetch data from previous node
const data = $('Code in JavaScript').first().json;

// 2. Normalize and override the time slot based on raw transcription keywords
let finalTimeSlot = data.time_time_slot_display || data.time_slot || "Not provided";
const rawText = (data.raw_text || "").toLowerCase().trim();

if (rawText.includes("subah") || rawText.includes("morning") || rawText.includes("subhah") || rawText.includes("suba")) {
    finalTimeSlot = "Morning (9:00-12:00)";
} else if (rawText.includes("dopahar") || rawText.includes("afternoon") || rawText.includes("dophr")) {
    finalTimeSlot = "Afternoon (12:00-16:00)";
} else if (rawText.includes("shaam") || rawText.includes("evening") || rawText.includes("sham")) {
    finalTimeSlot = "Evening (16:00-19:00)";
}

// 3. Extract variables smoothly
const name = data.name || "Unknown";
const date = data.date || "Not provided";
const reason = data.reason || "Not provided";
const phone = data.phone || "Not provided";
const booking_for = data.booking_for || "Self";
const time_slot = finalTimeSlot; 

// 4. Construct Hindi messaging variables
const booking_for_text = booking_for === "Self" ? "खुद के लिए" : `${booking_for} ke liye`;
const voice_confirmation = `${name} ji, aapki appointment ${date} ko ${time_slot} ke liye book ho gayi hai. ${booking_for === "Self" ? "" : booking_for + " ke liye."} Dhanyavaad!`;

// 5. Construct final valid multi-lingual TwiML response reading the confirmation
const twiml = `<?xml version="1.0" encoding="UTF-8"?><Response><Say language="hi-IN">${voice_confirmation}</Say></Response>`;

// 6. Build the text metadata notification 
const message = "New Appointment Booking\n\n" +
"Patient Name: " + name + "\n" +
"Phone Number: " + phone + "\n" +
"Appointment Date: " + date + "\n" +
"Time Slot: " + time_slot + "\n" +
"Medical Reason: " + reason + "\n" +
"Booking For: " + booking_for_text + "\n\n" +
"Booked via AI Voice Bot\n" +
"Time: " + new Date().toLocaleString('en-IN', {timeZone:'Asia/Kolkata'});

// 7. Output the final bundled object to the workflow
return [{ json: { ...data, whatsapp_message: message, voice_confirmation: voice_confirmation, twiml: twiml } }];
